class UPSBasePriceActivationJob extends RunBaseBatch implements BatchRetryable
{
    #OCCRetryCount

    QueryRun                    queryRun;

    NoYes                       netWeight;
    NoYes                       rateAndRatio;
    NoYes                       controlDate;
    NoYes                       skipActivationIfEqualPriceExists;
    NoYes                       abortOnError;
    NoYes                       recalculateProduction;

    UPSBasePriceVersionId       fromVersion;

    BatchHeader                 currentBatchHeader;

    DialogField                 dialogFieldNetWeight;
    DialogField                 dialogFieldRateAndRatio;
    DialogField                 dialogFieldControlDate;
    DialogField                 dialogFieldControlExistingPrice;
    DialogField                 dialogFieldAbortOnError;
    DialogField                 dialogFieldRecalculateProduction;

    boolean                     doNotUpdateLastActivationDate;

    #DEFINE.CurrentVersion(1)

    #LOCALMACRO.CurrentList
        netWeight,
        rateAndRatio,
        controlDate,
        skipActivationIfEqualPriceExists,
        fromVersion,
        abortOnError,
        recalculateProduction
    #ENDMACRO

}

Method.Source:
public static UPSBasePriceActivationJob construct()
{
    return new UPSBasePriceActivationJob();
}

public void initParmDefault()
{
    super();

    Query query = new Query();
    query.addDataSource(tableNum(UPSItemBasePriceSim));

    query.dataSourceTable(tableNum(UPSItemBasePriceSim)).addRange(fieldNum(UPSItemBasePriceSim, VersionId)).status(RangeStatus::Hidden);
    query.dataSourceTable(tableNum(UPSItemBasePriceSim)).addRange(fieldNum(UPSItemBasePriceSim, FromDate)).status(RangeStatus::Hidden);
    query.dataSourceTable(tableNum(UPSItemBasePriceSim)).addRange(fieldNum(UPSItemBasePriceSim, PriceType)).status(RangeStatus::Hidden);

    queryRun = new QueryRun(query);
}

public boolean unpack(container packedClass)
{
    container   packedQuery;
    Integer     version         = RunBase::getVersion(packedClass);

    switch (version)
    {
        case #CurrentVersion :
            [version, #CurrentList, packedQuery] = packedClass;

            if (packedQuery)
            {
                queryRun = new QueryRun(packedQuery);
            }
            break;

        default :
            return false;
    }

    return true;
}

public Object dialog()
{
    DialogRunbase dialog = super();

    dialog.addGroup("@SYS121351");
    dialog.addFieldValue(extendedTypeStr(UPSBasePriceVersionId), fromVersion).enabled(false);
    dialog.addFieldValue(extendedTypeStr(Name), UPSBasePriceVersion::find(fromVersion).Name).enabled(false);
    dialog.addGroup("@SYS121350");
    dialogFieldNetWeight            = dialog.addFieldValue(enumStr(NoYes), netWeight, "@SYS23743");
    dialogFieldRateAndRatio         = dialog.addFieldValue(enumStr(NoYes), rateAndRatio, "@SYS104960");

    dialog.addGroup("@SYS53323");
    dialogFieldControlDate          = dialog.addFieldValue(enumStr(NoYes), controlDate, "@SYS24050", "@SYS104995");
    dialogFieldControlExistingPrice = dialog.addFieldValue(enumStr(NoYes), skipActivationIfEqualPriceExists, "@SYP4882093", "@SYP4882094");

    dialog.addGroup("@SYS107201");
    dialogFieldAbortOnError         = dialog.addFieldValue(enumStr(NoYes), abortOnError, "@SYS105290", "@SYS105290");

    dialog.addGroup("@SYS4009911");
    dialogFieldRecalculateProduction = dialog.addFieldValue(enumStr(NoYes), recalculateProduction, "@SYS4009912");

    return dialog;
}

public boolean getFromDialog()
{
    boolean ret = super();

    netWeight                           = dialogFieldNetWeight.value();
    rateAndRatio                        = dialogFieldRateAndRatio.value();
    controlDate                         = dialogFieldControlDate.value();
    skipActivationIfEqualPriceExists    = dialogFieldControlExistingPrice.value();
    abortOnError                        = dialogFieldAbortOnError.value();
    recalculateProduction               = dialogFieldRecalculateProduction.value();

    return ret;
}

public static void main(Args args)
{
    UPSItemBasePriceSim             itemBasePriceSim;
    UPSBasePriceActivationJob       itemBasePriceActivationJob;
    boolean                         noActivePrice;
    boolean                         activateItemYesToAll;
    boolean                         activateItemNoToAll;
    boolean                         activateItemCancel;
    Common                          record;

    boolean activateItem()
    {
        UPSItemBasePrice    currentItemBasePrice;
        boolean             doActivate                = true;
        DialogButton        userResponse;

        if (activateItemNoToAll)
        {
            doActivate = false;
        }
        else
        {
            currentItemBasePrice = UPSItemBasePrice::findCurrent(itemBasePriceSim.ItemId,
                                                                    itemBasePriceSim.PriceType,
                                                                    itemBasePriceSim.InventDimId);
            userResponse = Box::yesAllNoAllCancel(strFmt("@UnifiedPricingService:UPSItemActivateOverwriteWarning",
                            currentItemBasePrice.ItemId,
                            currentItemBasePrice.VersionId,
                            currentItemBasePrice.ActivationDate,
                            date2StrUsr(itemBasePriceSim.FromDate, DateFlags::FormatAll)), DialogButton::No);

            if (userResponse == DialogButton::No || userResponse == DialogButton::NoToAll || userResponse == DialogButton::Cancel)
            {
                doActivate = false;
            }

            activateItemCancel = userResponse == DialogButton::Cancel;
            activateItemNoToAll = userResponse == DialogButton::NoToAll;
            activateItemYesToAll = userResponse == DialogButton::YesToAll;
        }

        return doActivate;
    }

    using (SysErrorMessageHelpScope scope = SysErrorMessageHelpScope::newErrorContext(args))
    {
        if (args && args.record() && args.dataset() == tableNum(UPSItemBasePriceSim))
        {                
            FormDataSource itemBasePriceSimDS = FormDataUtil::getFormDataSource(args.record());
            for (record = itemBasePriceSimDS.getFirst(true)
                        ? itemBasePriceSimDS.getFirst(true)
                        : itemBasePriceSimDS.cursor();
            record && !activateItemCancel;
            record = itemBasePriceSimDS.getNext())
            {
                itemBasePriceSim = record as UPSItemBasePriceSim;
                noActivePrice = itemBasePriceSim.checkNoActivePrice(false);

                if (itemBasePriceSim.allowActivation(false) && (activateItemYesToAll || activateItem()))
                {
                    itemBasePriceActivationJob  = UPSBasePriceActivationJob::construct();
                    itemBasePriceActivationJob.activateOneInventItemPriceSim(itemBasePriceSim);
                }
            }                        
        }
        else
        {
            throw error(Error::missingRecord(funcName()));
        }
    }
}

public boolean parmDoNotUpdateLastActivationDate(boolean _doNotUpdateLastActivationDate = doNotUpdateLastActivationDate)
{
    doNotUpdateLastActivationDate = _doNotUpdateLastActivationDate;
    return doNotUpdateLastActivationDate;
}

protected boolean activateOneInventItemPriceSim(UPSItemBasePriceSim _baseItemPriceSim)
{
    boolean priceActivated = false;
    UPSItemBasePriceSim baseItemPriceSim = _baseItemPriceSim;
    UPSBasePriceVersion basePriceVersion;

    #OCCRetryCount

    try
    {            
        if (!doNotUpdateLastActivationDate && baseItemPriceSim.FromDate != DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
        {
            info(strFmt("@UnifiedPricingService:UPSBasePriceActivationDateUpdate", baseItemPriceSim.ItemId, date2StrUsr(baseItemPriceSim.FromDate, DateFlags::FormatAll), date2StrUsr( DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), DateFlags::FormatAll)));
        }

        ttsbegin;

        baseItemPriceSim.moveSimulatedToCurrent();

        InventTableModule inventTableModule = InventTableModule::find(baseItemPriceSim.ItemId,
                                                                        ModuleInventPurchSales::Sales,
                                                                        true);
        inventTableModule.initFromUPSItemBasePriceSim(baseItemPriceSim);
        inventTableModule.update(false);

        UPSBasePriceVersion::updateActivationDate(baseItemPriceSim.VersionId);

        ttscommit;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    return priceActivated;
}
